        // 核心修复：前端图片压缩引擎
        // 无论用户上传多大的原图，都会被压缩到安全尺寸，彻底解决 localStorage 爆满导致的静默崩溃
        const compressImage = (file, maxWidth = 800, maxHeight = 800, quality = 0.6, cropSquare = false) => {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.readAsDataURL(file);
                reader.onload = event => {
                    if (file.type === 'image/gif') {
                        resolve(event.target.result);
                        return;
                    }
                    const img = new Image();
                    img.src = event.target.result;
                    img.onload = () => {
                        let width = img.width;
                        let height = img.height;
                        let offsetX = 0;
                        let offsetY = 0;

                        if (cropSquare) {
                            const size = Math.min(width, height);
                            offsetX = (width - size) / 2;
                            offsetY = (height - size) / 2;
                            width = size;
                            height = size;
                        }

                        let targetWidth = width;
                        let targetHeight = height;

                        if (targetWidth > maxWidth || targetHeight > maxHeight) {
                            if (targetWidth > targetHeight) {
                                targetHeight = Math.round((targetHeight *= maxWidth / targetWidth));
                                targetWidth = maxWidth;
                            } else {
                                targetWidth = Math.round((targetWidth *= maxHeight / targetHeight));
                                targetHeight = maxHeight;
                            }
                        }

                        try {
                            const canvas = document.createElement('canvas');
                            canvas.width = targetWidth;
                            canvas.height = targetHeight;
                            const ctx = canvas.getContext('2d');

                            if (cropSquare) {
                                ctx.drawImage(img, offsetX, offsetY, width, height, 0, 0, targetWidth, targetHeight);
                            } else {
                                ctx.drawImage(img, 0, 0, targetWidth, targetHeight);
                            }

                            const mimeType = file.type === 'image/png' ? 'image/png' : 'image/jpeg';
                            const dataUrl = canvas.toDataURL(mimeType, quality);
                            resolve(dataUrl);
                        } catch (e) {
                            console.warn('Image compression failed, using original', e);
                            resolve(event.target.result);
                        }
                    };
                    img.onerror = error => reject(error);
                };
                reader.onerror = error => reject(error);
            });
        };

