        const formatTime = (ts) => {
            const diff = Date.now() - ts;
            if (diff < 60000) return '刚刚';
            if (diff < 3600000) return Math.floor(diff/60000) + '分钟前';
            if (diff < 86400000) return Math.floor(diff/3600000) + '小时前';
            const d = new Date(ts), nd = new Date();
            if (d.getFullYear() === nd.getFullYear() && d.getMonth() === nd.getMonth() && nd.getDate() - d.getDate() === 1) return '昨天';
            if (d.getFullYear() === nd.getFullYear()) return `${d.getMonth()+1}月${d.getDate()}日`;
            return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日`;
        };

        const formatChatListTime = (ts) => {
            const d = new Date(ts);
            const now = new Date();
            
            const hours = d.getHours().toString().padStart(2, '0');
            const minutes = d.getMinutes().toString().padStart(2, '0');
            const timeStr = `${hours}:${minutes}`;
            
            const dateOnly = new Date(d.getFullYear(), d.getMonth(), d.getDate());
            const nowOnly = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            
            const diffDays = Math.floor((nowOnly - dateOnly) / (1000 * 60 * 60 * 24));
            
            if (diffDays === 0) {
                return timeStr;
            } else if (diffDays === 1) {
                return `昨天 ${timeStr}`;
            } else if (diffDays >= 2 && diffDays < 7) {
                const days = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
                return days[d.getDay()];
            } else {
                if (d.getFullYear() === now.getFullYear()) {
                    return `${d.getMonth() + 1}月${d.getDate()}日`;
                } else {
                    return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
                }
            }
        };

