        const bindPhotoInput = (inputId, key) => {
            const input = $(inputId);
            if (input) {
                on(input, 'change', async e => {
                    const f = e.target.files[0];
                    if (f) {
                        try {
                            // 提高小组件图片的清晰度
                            const isSquare = key === 'musicAvatar' || key === 'anniAvatar1' || key === 'anniAvatar2';
                            const compressedDataUrl = await compressImage(f, 1600, 1600, 0.95, isSquare);
                            homeWidgetsData[key] = compressedDataUrl;
                            store.set('home_widgets_data', homeWidgetsData);
                            renderHomeWidgets();
                        } catch (err) {
                            console.error('Image compression failed:', err);
                            showAlert('图片处理失败，请重试');
                        }
                        // 清空 input 的值，确保下次选择同一张图片也能触发 change 事件
                        e.target.value = '';
                    }
                });
            }
        };
