        window.saveShareMemorySelection = () => {
            const selectedIds = Array.from(document.querySelectorAll('.share-memory-cb:checked')).map(cb => cb.value);
            let oldSelectedIds = sharedMemories[currentChatFriendId] || [];
            if (oldSelectedIds === true) oldSelectedIds = friends.filter(g => g.isGroup && g.members && g.members.includes(currentChatFriendId)).map(g => g.id);
            
            sharedMemories[currentChatFriendId] = selectedIds;
            store.set('shared_memories', sharedMemories);
            $('share-memory-group-overlay').style.display = 'none';
            
            const sharedNames = selectedIds.map(id => friends.find(g => g.id === id)?.name).filter(Boolean);
            $('page-share-memory-display').textContent = sharedNames.length > 0 ? sharedNames.join(', ') : '未开启';

            // 同步以前的群聊记忆
            const newlyAddedGroups = selectedIds.filter(id => !oldSelectedIds.includes(id));
            if (newlyAddedGroups.length > 0) {
                let syncedCount = 0;
                newlyAddedGroups.forEach(groupId => {
                    const group = friends.find(g => g.id === groupId);
                    if (group) {
                        const groupMemData = chatMemories[groupId];
                        if (groupMemData && groupMemData.memories && groupMemData.memories.length > 0) {
                            groupMemData.memories.forEach(m => {
                                const syncText = `[在群聊"${group.name}"中发生的事件]: ${m.text}`;
                                const personalMemData = chatMemories[currentChatFriendId];
                                const alreadySynced = personalMemData && personalMemData.memories && personalMemData.memories.some(pm => pm.text === syncText);
                                
                                if (!alreadySynced) {
                                    Memory_Manager.addEpisodic(currentChatFriendId, syncText, '群聊同步', m.fuzzyTimeAnchor || '提取自历史');
                                    syncedCount++;
                                }
                            });
                        }
                    }
                });
                if (syncedCount > 0) {
                    showToast(`已同步 ${syncedCount} 条群聊记忆`);
                }
            }
        };

